{"files": {"style.css": ":root {
  --bg: #0b0f19; --fg: #e2e8f0; --mint: #34d399; --gold: #fbbf24; --ring: #f59e0b;
  --cell: #1e293b; --cell-hover: #334155; --focus: #60a5fa;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: system-ui, sans-serif; background: var(--bg); color: var(--fg); line-height: 1.5; }
main { max-width: 600px; margin: 0 auto; padding: 1rem; display: flex; flex-direction: column; gap: 1rem; }
header { text-align: center; }
.eyebrow { font-size: 0.875rem; color: var(--mint); text-transform: uppercase; letter-spacing: 0.1em; }
h1 { font-size: 2rem; margin: 0.5rem 0; }
nav { display: flex; gap: 0.5rem; flex-wrap: wrap; align-items: center; justify-content: center; }
select, button { padding: 0.5rem 1rem; border-radius: 0.5rem; border: 1px solid var(--fg); background: var(--cell); color: var(--fg); cursor: pointer; font-size: 1rem; }
button:hover { background: var(--cell-hover); }
button:focus-visible, select:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
.readout { text-align: center; font-size: 1.1rem; min-height: 1.5em; }
#board { display: grid; gap: 0.5rem; margin: 1rem auto; width: fit-content; }
#board button { width: 3rem; height: 3rem; border-radius: 50%; border: 2px solid transparent; background: var(--cell); color: transparent; font-size: 0; cursor: pointer; position: relative; transition: all 0.2s; }
#board button:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
#board button:hover:not(:disabled) { background: var(--cell-hover); transform: scale(1.05); }
#board button:disabled { opacity: 0.5; cursor: not-allowed; }
.peg { background: var(--mint); box-shadow: 0 0 10px var(--mint); }
.goal { border: 3px solid var(--gold); box-shadow: 0 0 15px var(--gold); }
.selected { background: var(--gold); box-shadow: 0 0 20px var(--gold); transform: scale(1.1); }
.target { border: 3px dashed var(--ring); animation: pulse 1.5s infinite; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.6; } }
footer { text-align: center; font-size: 0.875rem; color: #94a3b8; margin-top: 1rem; }
@media (max-width: 400px) { #board button { width: 2.5rem; height: 2.5rem; } h1 { font-size: 1.5rem; } }
@media (min-width: 600px) { #board button { width: 3.5rem; height: 3.5rem; } }"}}
